@startuml

abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

abstract class ContractDecorator extends Contract {
}

class DataOption extends ContractDecorator {
  + getCharges() : double
}

class SmsOption extends ContractDecorator {
  + getCharges() : double
}

class MinutesOption extends ContractDecorator {
  + getCharges() : double
}

class TransferRateOption extends ContractDecorator {
  + getCharges() : double
}

Contract "1" -- "0..*" ContractDecorator : decorates

@enduml

